import React, { useState } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import { verifyOtp, forgotPassword, resetPassword } from '../services/api';

export function VerifyOtp() {
  const navigate = useNavigate();
  const location = useLocation();
  const [email] = useState(location.state?.email || '');
  const [otp, setOtp] = useState('');
  const [msg, setMsg] = useState('');
  const [error, setError] = useState('');

  const submit = async (e) => {
    e.preventDefault(); setError(''); setMsg('');
    try {
      const res = await verifyOtp({ email, otp });
      if (res.data.success) { setMsg('Verified! Redirecting…'); setTimeout(() => navigate('/login'), 1500); }
      else setError(res.data.message);
    } catch { setError('Server error'); }
  };

  return (
    <div className="auth-page">
      <div className="auth-card">
        <div className="auth-logo">⚡ InternHub</div>
        <p className="auth-subtitle">Enter the 6-digit OTP sent to <strong>{email}</strong></p>
        {msg && <div className="alert alert-success">{msg}</div>}
        {error && <div className="alert alert-error">{error}</div>}
        <form onSubmit={submit}>
          <div className="form-group">
            <label>OTP</label>
            <input className="form-control" value={otp} onChange={e => setOtp(e.target.value)}
              required placeholder="123456" maxLength={6} style={{ letterSpacing: '4px', fontSize: '1.2rem', textAlign: 'center' }} />
          </div>
          <button className="btn btn-primary" type="submit" style={{ width: '100%' }}>Verify Email</button>
        </form>
      </div>
    </div>
  );
}

export function ForgotPassword() {
  const navigate = useNavigate();
  const [step, setStep] = useState(1);
  const [email, setEmail] = useState('');
  const [otp, setOtp] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [msg, setMsg] = useState('');
  const [error, setError] = useState('');

  const sendOtp = async (e) => {
    e.preventDefault(); setError('');
    try {
      const res = await forgotPassword({ email });
      if (res.data.success) { setMsg(res.data.message); setStep(2); }
      else setError(res.data.message);
    } catch { setError('Server error'); }
  };

  const reset = async (e) => {
    e.preventDefault(); setError('');
    try {
      const res = await resetPassword({ email, otp, newPassword });
      if (res.data.success) { setMsg('Password reset! Redirecting…'); setTimeout(() => navigate('/login'), 1500); }
      else setError(res.data.message);
    } catch { setError('Server error'); }
  };

  return (
    <div className="auth-page">
      <div className="auth-card">
        <div className="auth-logo">⚡ InternHub</div>
        <p className="auth-subtitle">{step === 1 ? 'Reset your password' : 'Enter OTP & new password'}</p>
        {msg && <div className="alert alert-success">{msg}</div>}
        {error && <div className="alert alert-error">{error}</div>}
        {step === 1 ? (
          <form onSubmit={sendOtp}>
            <div className="form-group">
              <label>Email address</label>
              <input className="form-control" type="email" value={email} onChange={e => setEmail(e.target.value)} required />
            </div>
            <button className="btn btn-primary" type="submit" style={{ width: '100%' }}>Send OTP</button>
          </form>
        ) : (
          <form onSubmit={reset}>
            <div className="form-group">
              <label>OTP</label>
              <input className="form-control" value={otp} onChange={e => setOtp(e.target.value)} required maxLength={6} />
            </div>
            <div className="form-group">
              <label>New Password</label>
              <input className="form-control" type="password" value={newPassword} onChange={e => setNewPassword(e.target.value)} required />
            </div>
            <button className="btn btn-primary" type="submit" style={{ width: '100%' }}>Reset Password</button>
          </form>
        )}
        <p style={{ textAlign: 'center', marginTop: '1rem', fontSize: '0.85rem', color: 'var(--text2)' }}>
          <Link to="/login" style={{ color: 'var(--accent2)' }}>← Back to login</Link>
        </p>
      </div>
    </div>
  );
}

export default VerifyOtp;
